#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct VersionPolicy {
    /// How many replaced versions to keep. 0 keeps none.
    pub keep_count: u64,
    /// Days a version is kept, counted from when it was replaced (not created). 0 means no age limit.
    pub keep_days: u64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct VersionsResponse {
    pub item_id: ItemId,
    pub versions: Vec<Version>,
    pub freshness: Freshness,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Volume {
    pub volume_id: String,
    pub label: String,
    pub kind: VolumeKind,
    pub total_bytes: u64,
    pub free_bytes: u64,
    pub removable: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub encrypted: Option<bool>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum VolumeKind {
    #[serde(rename = "internal")]
    Internal,
    #[serde(rename = "external")]
    External,
    #[serde(rename = "network")]
    Network,
    #[serde(rename = "cloud_disk")]
    CloudDisk,
}

impl VolumeKind {
    pub const ALL: &'static [Self] = &[Self::Internal, Self::External, Self::Network, Self::CloudDisk];
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Internal => "internal",
            Self::External => "external",
            Self::Network => "network",
            Self::CloudDisk => "cloud_disk",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WakeConsentRequest {
    pub reason: WakeReason,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub item_id: Option<ItemId>,
    pub device_id: DeviceId,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WakeConsentResponse {
    /// Send as X-Allternit-Wake-Ticket.
    pub ticket: String,
    pub expires_at: Timestamp,
    pub computer_state: WakeConsentResponseComputerState,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub estimated_wake_s: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum WakeConsentResponseComputerState {
    #[serde(rename = "waking")]
    Waking,
    #[serde(rename = "awake")]
    Awake,
}

impl WakeConsentResponseComputerState {
    pub const ALL: &'static [Self] = &[Self::Waking, Self::Awake];
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Waking => "waking",
            Self::Awake => "awake",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WakeHint {
    pub setting: WakeSetting,
    /// cloud-api path to POST for a wake ticket, e.g. /api/v1/computer-files/<id>/wake-consent.
    pub consent_path: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum WakeReason {
    #[serde(rename = "open_file")]
    OpenFile,
    #[serde(rename = "upload")]
    Upload,
    #[serde(rename = "search_content")]
    SearchContent,
    #[serde(rename = "sync")]
    Sync,
    #[serde(rename = "replica_restore")]
    ReplicaRestore,
    #[serde(rename = "share_access")]
    ShareAccess,
}

impl WakeReason {
    pub const ALL: &'static [Self] = &[Self::OpenFile, Self::Upload, Self::SearchContent, Self::Sync, Self::ReplicaRestore, Self::ShareAccess];
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::OpenFile => "open_file",
            Self::Upload => "upload",
            Self::SearchContent => "search_content",
            Self::Sync => "sync",
            Self::ReplicaRestore => "replica_restore",
            Self::ShareAccess => "share_access",
        }
    }
}

/// Per computer. Default ask.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum WakeSetting {
    #[serde(rename = "ask")]
    Ask,
    #[serde(rename = "auto")]
    Auto,
    #[serde(rename = "never")]
    Never,
}

impl WakeSetting {
    pub const ALL: &'static [Self] = &[Self::Ask, Self::Auto, Self::Never];
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Ask => "ask",
            Self::Auto => "auto",
            Self::Never => "never",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WakeSettings {
    pub computer_id: ComputerId,
    pub wake: WakeSetting,
}

/// Decoded body of a wake ticket. Ed25519-signed by cloud-api. Single use per jti.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WakeTicketClaims {
    pub v: u64,
    pub typ: String,
    /// User ID.
    pub sub: String,
    pub computer_id: ComputerId,
    pub reason: WakeReason,
    pub device_id: DeviceId,
    pub iat: u64,
    /// At most iat + 300.
    pub exp: u64,
    pub jti: String,
    pub kid: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WhoAmIResponse {
    pub principal: PrincipalRef,
    pub computer_id: ComputerId,
    pub grants: Vec<RootGrant>,
    pub freshness: Freshness,
}
